const input=$json??{}; const event=input.event??input;
const dealId=event.deal_id??event.dealId, leadId=event.lead_id??event.leadId, propertyId=event.property_id??event.propertyId;
const channel=String(event.channel??event.preferred_channel??'').toLowerCase();
const message=String(event.message??event.body??event.generated_message??'').trim();
const phone=event.phone??event.seller?.phone, email=event.email??event.seller?.email;
const dnc=Boolean(event.dnc??event.do_not_contact), blockers=Array.isArray(event.blockers)?event.blockers:[];
const approved=event.dispatch_authorized===true||event.authorized===true;
const attempts=Number(event.attempts??0), maxAttempts=Number(event.max_attempts??3);
const baseKey=event.idempotency_key??[dealId,leadId,propertyId,'seller-followup'].filter(Boolean).join(':');
const dispatchKey=baseKey+':provider-dispatch:'+attempts;
let route='WF-358',decision='dispatch_package_invalid',reason='not_ready';
if(dnc){route='WF-126';decision='dnc_hard_stop';reason='dnc_or_opt_out';}
else if(blockers.length){route='WF-126';decision='blocked';reason='operational_blocker';}
else if(!dealId||!leadId||!propertyId||!baseKey){route='WF-358';decision='identity_or_idempotency_missing';reason='required_identity_missing';}
else if(attempts>=maxAttempts){route='WF-126';decision='human_review_max_attempts';reason='outreach_limit_reached';}
else if(!['sms','email'].includes(channel)){route='WF-358';decision='unsupported_channel';reason='channel_not_supported';}
else if(channel==='sms'&&!phone){route='WF-358';decision='contact_missing';reason='sms_recipient_missing';}
else if(channel==='email'&&!email){route='WF-358';decision='contact_missing';reason='email_recipient_missing';}
else if(!message){route='WF-358';decision='message_missing';reason='generated_message_missing';}
else if(!approved){route='WF-347';decision='dispatch_authorization_required';reason='provider_dispatch_not_authorized';}
else {route='WF-347';decision='dispatch_package_ready';reason='validated_and_authorized';}
return [{json:{...event,workflow:'WF-359',decision,reason,route,deal_id:dealId,lead_id:leadId,property_id:propertyId,channel,message,phone,email,attempts,max_attempts:maxAttempts,dispatch_authorized:approved,provider_dispatch_idempotency_key:dispatchKey,dispatch_package:{channel,recipient:channel==='sms'?phone:email,message,deal_id:dealId,lead_id:leadId,property_id:propertyId},audit_event:'message_generation_provider_dispatch_validation_authorization'}}];
